import type LockingScript from '@bsv/sdk/script/LockingScript'
import type { LookupNetworkPreset } from '@bsv/sdk/overlay-tools/LookupResolver'
import type {
  AtomicBEEF,
  Base64String,
  BasketStringUnder300Bytes,
  BEEF,
  BooleanDefaultTrue,
  DescriptionString5to50Bytes,
  HexString,
  LabelStringUnder300Bytes,
  OutputTagStringUnder300Bytes,
  PositiveIntegerOrZero,
  PubKeyHex,
  WalletInterface
} from '@bsv/sdk/wallet/Wallet.interfaces'
import type { AuthSocketClientOptions } from '@bsv/authsocket-client'

/**
 * Socket.IO manager/socket options forwarded to AuthSocketClient.
 * `autoConnect` is excluded: AuthSocketClient exposes no connect method and the
 * client never starts the socket itself, so disabling auto-connect would leave
 * `initializeConnection` waiting for an authentication that cannot arrive.
 * `retries` is excluded because AuthSocket acknowledges authenticated messages
 * through its protocol, not the Socket.IO acknowledgements required by retries.
 */
export type MessageBoxForwardedManagerOptions = Omit<
  NonNullable<AuthSocketClientOptions['managerOptions']>,
  'autoConnect' | 'retries'
>

/**
 * AuthSocketClient options a MessageBoxClient caller may supply.
 * `wallet` and `originator` are owned by the client and always win.
 */
export type MessageBoxSocketOptions = Omit<
  AuthSocketClientOptions,
  'wallet' | 'originator' | 'managerOptions'
> & { managerOptions?: MessageBoxForwardedManagerOptions }

/**
 * Configuration options for initializing a MessageBoxClient.
 */
export interface MessageBoxClientOptions {
  /**
   * Wallet instance used for auth, identity, and encryption.
   * If not provided, a new WalletClient will be created.
   */
  walletClient?: WalletInterface

  /**
   * Base URL of the MessageBox server.
   * Required when networkPreset is 'teratestnet'.
   * @default 'https://message-box-us-1.bsvb.tech' for mainnet and testnet
   */
  host?: string

  /**
   * Optional BRC-103 server identity pins keyed by Message Box base URL.
   * Keys are normalized to their URL origin, so route-prefixed URLs on the
   * same origin must name the same identity. When omitted, the first mutually
   * authenticated identity observed for each origin is authoritative for this
   * client instance; later identity changes fail closed.
   */
  serverIdentityKeysByHost?: Readonly<Record<string, PubKeyHex>>

  /**
   * If true, enables detailed logging to the console.
   * @default false
   */
  enableLogging?: boolean

  /**
   * Overlay network preset for routing resolution.
   * @default 'mainnet'
   */
  networkPreset?: LookupNetworkPreset

  /**
   * Originator of the message box client.
   */
  originator?: string

  /**
   * Options forwarded to the underlying AuthSocketClient when the live socket is
   * created. Covers socket.io transport selection via `managerOptions` (e.g.
   * `{ managerOptions: { transports: ['websocket'] } }` for a deployment that does
   * not carry Engine.IO HTTP polling), plus certificate requests, session
   * management, auth-message concurrency, and error reporting.
   *
   * `wallet` and `originator` are excluded because the client owns both; the
   * client's own values always win. Only affects the socket path; HTTP requests
   * are unchanged.
   */
  socketOptions?: MessageBoxSocketOptions
}

/**
 * What the live socket is doing, as the client knows it. Reported rather than
 * inferred: before this, a consumer could only find out by sending.
 *
 * - `connecting` — a socket exists and has not authenticated yet.
 * - `live` — authenticated; `rooms` are the rooms joined on it (see
 *   {@link LiveStatus.rooms}).
 * - `reconnecting` — dropped, and something will restore it: Socket.IO's own
 *   retry, or a rebuild this client has scheduled.
 * - `closed` — dropped, and nothing will restore it. A deliberate
 *   `disconnectWebSocket()`, a drop under `managerOptions.reconnection: false`,
 *   or a rebuild that was tried and failed. The next call that needs a socket
 *   still builds one.
 */
export type LiveConnectionState = 'connecting' | 'live' | 'reconnecting' | 'closed'

/** A live-socket state and the rooms joined on it, as `onLiveStatus` reports it. */
export interface LiveStatus {
  state: LiveConnectionState
  /**
   * Rooms joined on the current socket: requested and not refused by the
   * server. Recorded when requested, before the server answers; a `joinFailed`
   * removes one. Empty unless `state` is `live`.
   */
  rooms: readonly string[]
  /** Socket.IO's disconnect reason, when the state came from a drop. */
  reason?: string
}

/**
 * Represents a decrypted message received from a MessageBox.
 * Includes metadata such as sender identity, timestamps, and optional acknowledgment status.
 *
 * Used in both HTTP and WebSocket message retrieval responses.
 */
export interface PeerMessage {
  messageId: string
  body: string | Record<string, any>
  sender: string
  created_at: string
  updated_at: string
  acknowledged?: boolean
  /**
   * What `listMessages` or `listMessagesLite` did with the payment this message
   * carried. Set only on messages that carried one.
   */
  paymentOutcome?: PeerMessagePaymentOutcome
  /**
   * The payment from the stored-message envelope, exactly as the server
   * returned it: shaped like {@link Payment} when well formed, but not
   * validated, so validate it before use (after a `'failed'` outcome it may be
   * malformed). Kept whenever `paymentOutcome` is not `'internalized'`: the
   * message holds the only copy of its derivation data, so store the payment
   * before acknowledging the message.
   */
  payment?: Record<string, unknown>
}

/**
 * How the list call processed a message's payment (not whether it was later
 * spent or refunded):
 * - `'internalized'`: the wallet accepted the payment.
 * - `'failed'`: internalizing threw or the wallet did not accept it.
 * - `'skipped'`: not attempted (`acceptPayments: false`, or `listMessagesLite`).
 * - `'no-wallet-outputs'`: it has no `wallet payment` outputs to internalize.
 */
export type PeerMessagePaymentOutcome = 'internalized' | 'failed' | 'skipped' | 'no-wallet-outputs'

/**
 * Parameters required to send a message.
 * Message content may be a string or object, and encryption is enabled by default.
 *
 * @example
 * {
 *   recipient: "03abc...",
 *   messageBox: "payment_inbox",
 *   body: { type: "ping" },
 *   skipEncryption: false
 * }
 */
export interface SendMessageParams {
  recipient: string
  messageBox: string
  body: string | object
  messageId?: string
  skipEncryption?: boolean
  /** Optional: Enable permission and fee checking (default: false for backwards compatibility) */
  checkPermissions?: boolean
  /** Optional caller-enforced ceiling for an automatically created permission payment. */
  maximumPayment?: PositiveIntegerOrZero
}

/**
 * Server response structure for successful message delivery.
 *
 * Returned by both `sendMessage` and `sendLiveMessage`.
 */
export interface SendMessageResponse {
  status: string
  messageId: string
  /** Optional bounded informational message returned by the server. */
  message?: string
}

/**
 * Parameters for acknowledging messages in the system.
 *
 * @interface AcknowledgeMessageParams
 *
 * @property {string[]} messageIds - An array of message IDs to acknowledge.
 * @property {string} [host] - Optional host URL where the messages originated.
 */
export interface AcknowledgeMessageParams {
  messageIds: string[]
  host?: string
}

/**
 * Parameters for listing messages in a message box.
 *
 * @property messageBox - The identifier of the message box to retrieve messages from.
 * @property host - (Optional) The host URL to connect to for retrieving messages.
 */
export interface ListMessagesParams {
  messageBox: string
  host?: string
  /** Optional exact message identifier for a bounded indexed lookup. */
  messageId?: string
  acceptPayments?: boolean
  /** Starting message offset. `skip` is an equivalent compatibility alias. */
  offset?: number
  /** Compatibility alias for `offset`; both values must match when supplied together. */
  skip?: number
  /** Maximum total messages accumulated by this call. Omit to retain fetch-all behavior. */
  limit?: number
  /** Per-request server page size. Omit to use the server operator's configured default. */
  pageSize?: number
  /** Optional pagination safety ceiling. Defaults to -1 to preserve fetch-all compatibility. */
  maxPages?: number
}

/**
 * Encapsulates an AES-256-GCM encrypted message body.
 *
 * Used when transmitting encrypted payloads to the MessageBox server.
 */
export interface EncryptedMessage {
  encryptedMessage: Base64String
}

export interface AdvertisementToken {
  host: string
  txid: HexString
  outputIndex: number
  lockingScript: LockingScript
  beef: BEEF
}

export interface Payment {
  tx: AtomicBEEF
  outputs: Array<{
    outputIndex: PositiveIntegerOrZero
    protocol: 'wallet payment' | 'basket insertion'
    paymentRemittance?: {
      derivationPrefix: Base64String
      derivationSuffix: Base64String
      senderIdentityKey: PubKeyHex
    }
    insertionRemittance?: {
      basket: BasketStringUnder300Bytes
      customInstructions?: string
      tags?: OutputTagStringUnder300Bytes[]
    }
  }>
  description: DescriptionString5to50Bytes
  labels?: LabelStringUnder300Bytes[]
  seekPermission?: BooleanDefaultTrue
}

/**
 * Device registration parameters for FCM notifications
 */
export interface DeviceRegistrationParams {
  /** FCM token from Firebase SDK */
  fcmToken: string
  /** Optional device identifier */
  deviceId?: string
  /** Optional platform type */
  platform?: 'ios' | 'android' | 'web'
}

/**
 * Device registration response
 */
export interface DeviceRegistrationResponse {
  status: string
  message: string
  deviceId: number
}

/**
 * Registered device information
 */
export interface RegisteredDevice {
  id: number
  deviceId: string | null
  platform: string | null
  fcmToken: string // Truncated for security (shows only last 10 characters)
  active: boolean
  createdAt: string
  updatedAt: string
  lastUsed: string
}

/**
 * Response from listing registered devices
 */
export interface ListDevicesResponse {
  status: string
  devices: RegisteredDevice[]
  description?: string // For error responses
}

/**
 * Base fields shared by both payment request and cancellation messages.
 */
interface PaymentRequestBase {
  /** Unique identifier for this request, generated via createNonce(). */
  requestId: string
  /** Identity key of the requester, used for correlation and cancellation verification. */
  senderIdentityKey: string
}

/**
 * A new payment request sent from requester to payer.
 * Carried in the 'payment_requests' message box.
 */
export interface PaymentRequestNew extends PaymentRequestBase {
  /** Amount in satoshis being requested. */
  amount: number
  /** Human-readable reason for the request. */
  description: string
  /** Unix timestamp (ms) after which the request expires. Set by the sender. */
  expiresAt: number
  /** HMAC proof tying this request to the sender's identity. Used to authorize cancellations. */
  requestProof: string
  /** Omitted or false for a new payment request. */
  cancelled?: false
}

/**
 * A cancellation of a previously sent payment request.
 * Carried in the 'payment_requests' message box.
 */
export interface PaymentRequestCancellation extends PaymentRequestBase {
  /** If true, this message cancels a previously sent request with the same requestId. */
  cancelled: true
  /** HMAC proof from the original request, proving cancellation authority. */
  requestProof: string
}

/**
 * Discriminated union: either a new payment request or a cancellation.
 * Discriminant field: `cancelled` (true = cancellation, absent/false = new request).
 */
export type PaymentRequestMessage = PaymentRequestNew | PaymentRequestCancellation

/**
 * Represents a response to a payment request, sent from the payer back to the requester.
 * Carried in the 'payment_request_responses' message box.
 */
export interface PaymentRequestResponse {
  /** Authenticated envelope message ID. Present on list/live receive results, absent on send bodies. */
  messageId?: string
  /** Authenticated envelope sender. Present on list/live receive results, absent on send bodies. */
  sender?: string
  /** The requestId of the original PaymentRequestMessage this responds to. */
  requestId: string
  /** Status of the response. */
  status: 'paid' | 'declined'
  /** Optional note from the payer. */
  note?: string
  /** Actual amount paid in satoshis (may differ from the requested amount). */
  amountPaid?: number
}

/**
 * Represents an incoming payment request as returned by listIncomingPaymentRequests().
 * Combines the transport message metadata with the parsed request body.
 * Only active (non-cancelled) requests are returned, so cancelled field is omitted.
 */
export interface IncomingPaymentRequest {
  /** Transport message ID used for acknowledgment. */
  messageId: string
  /** Identity key of the requester. */
  sender: string
  /** Unique identifier for this request. */
  requestId: string
  /** Amount in satoshis requested. */
  amount: number
  /** Human-readable reason for the request. */
  description: string
  /** Unix timestamp (ms) when the request expires. */
  expiresAt: number
}

/**
 * A token transfer carried in a token message box (the token analog of
 * PaymentToken). The derivation values let the recipient's wallet re-derive
 * the owner key and take custody; protocol/assetId/amount route it to the
 * right TokenSettlementAdapter on the receiving side.
 */
export interface TokenToken {
  protocol: string
  assetId: string
  /** Token units as a string (bigint-safe). */
  amount: string
  customInstructions: { derivationPrefix: Base64String; derivationSuffix: Base64String }
  transaction: AtomicBEEF
  outputIndex?: number
  /** Broadcast txid of the transfer, surfaced by the adapter (explorer links). */
  txid?: string
}

/** An incoming token received via MessageBox (token analog of IncomingPayment). */
export interface IncomingToken {
  messageId: string
  sender: string
  token: TokenToken
}

/** A new token-transfer request (token analog of PaymentRequestNew). */
export interface TokenRequestNew extends PaymentRequestBase {
  protocol: string
  assetId: string
  /** Token units requested, as a string. */
  amount: string
  description: string
  expiresAt: number
  requestProof: string
  cancelled?: false
}

export interface TokenRequestCancellation extends PaymentRequestBase {
  cancelled: true
  requestProof: string
}

export type TokenRequestMessage = TokenRequestNew | TokenRequestCancellation

export interface TokenRequestResponse {
  requestId: string
  status: 'sent' | 'declined'
  protocol?: string
  assetId?: string
  amountSent?: string
  note?: string
}

export interface IncomingTokenRequest {
  messageId: string
  sender: string
  requestId: string
  protocol: string
  assetId: string
  amount: string
  description: string
  expiresAt: number
}

/** Default minimum satoshis for payment request filtering. */
export const DEFAULT_PAYMENT_REQUEST_MIN_AMOUNT = 1000
/** Default maximum satoshis for payment request filtering. */
export const DEFAULT_PAYMENT_REQUEST_MAX_AMOUNT = 10_000_000

/**
 * Configurable min/max amount limits for incoming payment requests.
 * Requests outside these bounds are auto-acknowledged and discarded.
 */
export interface PaymentRequestLimits {
  /** Minimum satoshis to accept in a request. Requests below this are discarded. Default: 1000. */
  minAmount?: number
  /** Maximum satoshis to accept in a request. Requests above this are discarded. Default: 10000000. */
  maxAmount?: number
}
